def products_to_setup(apps, schema_editor):
    """Products remembered from drawings become project setup rows named as in Callidus."""
    Product = apps.get_model("jobs", "Product")
    for p in Product.objects.all():
        if p.callidus_material:
            p.name = p.callidus_material
            p.save(update_fields=["name"])
        elif p.spec_source.startswith("Confirmed on"):
            p.delete()  # a finish left out on a drawing: not a product


